"""The PSAQ-ViT baseline: images generated by an ImageNet classifier, for detection QAT.

PSAQ-ViT (https://arxiv.org/abs/2203.02250) generates images that a vision transformer classifier
assigns to random ImageNet classes, while maximizing the entropy of its patch similarities. This
port follows the old `vit/baseline/psaq/` exactly as it ran, which always used Swin-T:

- the classifier is the detection Swin-T backbone with the official ImageNet weights, converted
  as MMDetection's `swin_converter` does, average-pooled stage-4 features, and the ImageNet head;
- the checkpoint's final `norm` matched no backbone key, so `norm3` stayed at identity; this is
  the default here too, and `load_final_norm` loads it (a corrected baseline);
- each batch runs two rounds of 500 steps (jitter of up to 15, then 30 pixels; random flips),
  minimizing cross-entropy + 0.05 |TV_L2 - v| - entropy, with `v` uniform in [2500, 3000];
- every image gets one dummy box of class 0, since QAT needs targets.
"""

import random
from pathlib import Path

import torch
import torch.nn.functional as F
from torch import Tensor, nn

from dfq.detection import Targets
from dfq.detection.taps import tap
from dfq.models.maskrcnn.swin import AttentionValues, SwinTransformer
from dfq.synthesis.generate import (
    GenerationConfig,
    Init,
    LatentSpace,
    Schedule,
    clamp_to_image,
    learning_rate,
    to_pixels,
)
from dfq.synthesis.priors import patch_similarity_entropy, total_variation

IMAGENET = LatentSpace(mean=(0.485, 0.456, 0.406), std=(0.229, 0.224, 0.225))
DUMMY_BOX = (0.0, 25.8699, 189.7085, 158.4098)


class SwinClassifier(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.backbone = SwinTransformer((2, 2, 6, 2), drop_path_rate=0.0)
        self.head = nn.Linear(768, 1000)

    def forward(self, images: Tensor) -> Tensor:
        features = self.backbone(images)["3"]
        pooled = features.flatten(2).mean(dim=2)
        logits: Tensor = self.head(pooled)
        return logits


def unfold_order(weight: Tensor) -> Tensor:
    """Reorder patch-merging inputs from the official `x0 x1 x2 x3` concatenation to `nn.Unfold`."""
    if weight.ndim == 2:
        out_channels, in_channels = weight.shape
        grouped = weight.reshape(out_channels, 4, in_channels // 4)[:, [0, 2, 1, 3], :]
        return grouped.transpose(1, 2).reshape(out_channels, in_channels)
    grouped = weight.reshape(4, weight.shape[0] // 4)[[0, 2, 1, 3], :]
    return grouped.transpose(0, 1).reshape(weight.shape[0])


def official_key(key: str) -> str:
    key = key.replace("layers.", "stages.", 1).replace("patch_embed.proj", "patch_embed.projection")
    key = key.replace("attn.", "attn.w_msa.").replace("mlp.fc1.", "ffn.layers.0.0.")
    return key.replace("mlp.fc2.", "ffn.layers.1.")


def load_classifier(weights: Path, load_final_norm: bool = False) -> SwinClassifier:
    """Load the official `swin_tiny_patch4_window7_224.pth`."""
    state = torch.load(weights, map_location="cpu", weights_only=True)["model"]
    classifier = SwinClassifier()
    converted = {}
    for key, value in state.items():
        if key.startswith("head."):
            converted[key] = value
        elif key.startswith("norm.") and load_final_norm:
            converted["backbone.norm3." + key.removeprefix("norm.")] = value
        elif key.startswith(("layers.", "patch_embed.")) and not key.endswith("attn_mask"):
            reordered = unfold_order(value) if ".downsample." in key else value
            converted["backbone." + official_key(key)] = reordered
    missing, unexpected = classifier.load_state_dict(converted, strict=False)
    unused_norms = range(3) if load_final_norm else range(4)
    expected_missing = {f"backbone.norm{i}.{p}" for i in unused_norms for p in ("weight", "bias")}
    if set(missing) != expected_missing or unexpected:
        raise ValueError(f"weights do not fit: missing {missing}, unexpected {unexpected}")
    return classifier


def generate_psaq_batch(
    classifier: SwinClassifier, batch_size: int, steps: int, device: torch.device
) -> Tensor:
    """One batch of 640 x 640 images in pixels."""
    latent = torch.randn((batch_size, 3, 640, 640), device=device).requires_grad_()
    optimizer = torch.optim.Adam([latent], lr=0.25, betas=(0.5, 0.9), eps=1e-8)
    classes = torch.tensor([random.randint(0, 999) for _ in range(batch_size)], device=device)
    tv_target = random.uniform(2500, 3000)
    schedule = GenerationConfig(
        iterations=steps,
        lr=0.25,
        schedule=Schedule.WARMUP_COSINE,
        warmup=100,
        init=Init.NORMAL_LATENT,
    )
    names = [name for name, m in classifier.named_modules() if isinstance(m, AttentionValues)]
    for limit in (15, 30):
        for step in range(1, steps + 1):
            for group in optimizer.param_groups:
                group["lr"] = learning_rate(schedule, step)
            shift = random.randint(-limit, limit)
            jittered = torch.roll(latent, shifts=(shift, shift), dims=(2, 3))
            if random.random() > 0.5:
                jittered = torch.flip(jittered, dims=(3,))
            with tap(classifier, names) as attention:
                logits = classifier(jittered)
            outputs = [attention[name] for name in names]
            entropy = patch_similarity_entropy(
                [o for o in outputs if isinstance(o, Tensor)], batch_size
            )
            _, tv_l2 = total_variation(jittered)
            loss = F.cross_entropy(logits, classes) + 0.05 * (tv_l2 - tv_target).abs() - entropy
            optimizer.zero_grad()
            loss.backward()
            optimizer.step()
            clamp_to_image(latent, IMAGENET)
    return to_pixels(latent.detach(), IMAGENET)


def dummy_targets(count: int) -> list[Targets]:
    box = torch.tensor([DUMMY_BOX])
    return [
        Targets(boxes=box.clone(), labels=torch.zeros(1, dtype=torch.int64)) for _ in range(count)
    ]
